create extension if not exists pgcrypto;
create table if not exists public.habits(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,name text not null,icon text not null default 'sparkles',frequency text not null default 'Todos os dias',sort_order integer not null default 100,created_at timestamptz not null default now());
create table if not exists public.habit_completions(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,habit_id uuid not null references public.habits(id) on delete cascade,completed_on date not null default current_date,unique(user_id,habit_id,completed_on));
create table if not exists public.thesis_tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,title text not null,start_date date not null,end_date date not null,is_done boolean not null default false,sort_order integer not null default 100,created_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.measurements(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,measured_month date not null,weight numeric(5,2) not null check(weight>0),waist numeric(5,2),hip numeric(5,2),chest numeric(5,2),thigh numeric(5,2),arm numeric(5,2),created_at timestamptz not null default now(),unique(user_id,measured_month));
alter table public.habits enable row level security;alter table public.habit_completions enable row level security;alter table public.thesis_tasks enable row level security;alter table public.measurements enable row level security;
do $$ declare t text; begin foreach t in array array['habits','habit_completions','thesis_tasks','measurements'] loop execute format('drop policy if exists "Users manage own rows" on public.%I',t);execute format('create policy "Users manage own rows" on public.%I for all using (auth.uid()=user_id) with check (auth.uid()=user_id)',t);end loop;end $$;
grant usage on schema public to anon,authenticated;grant select,insert,update,delete on public.habits,public.habit_completions,public.thesis_tasks,public.measurements to authenticated;
